assert set(STORIES) == set(range(31, 61))
for z, items in STORIES.items():
    assert len(items) == 5, z
    titles = [i["title"] for i in items]
    assert len(set(titles)) == 5, z
    for item in items:
        assert 2 <= len(item["title"].split()) <= 8, (z, item["title"])
        assert len(item["summary"].split()) >= 12, (z, item["title"])
        assert len(item["story"].split()) >= 80, (z, item["title"], len(item["story"].split()))

